extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var question_script = load("res://question.gd")
	var session_script = load("res://quiz_session.gd")
	if not check("scripts", question_script != null and session_script != null, "Gli script di Question e QuizSession devono caricarsi senza errori"):
		return
	var q1 = question_script.new("Q1", ["A", "B"], 0)
	var q2 = question_script.new("Q2", ["A", "B"], 0)
	var session = session_script.new([q1, q2])
	if not check("init_q", session.get_current_question() == q1, "All'inizio la domanda corrente deve essere la prima"):
		return
	session.submit_answer(0)
	if not check("submit_no_skip", session.get_current_question() == q1, "Inviare una risposta con submit_answer() non deve far avanzare subito alla domanda successiva"):
		return
	session.advance()
	if not check("advance_next", session.get_current_question() == q2, "Dopo advance() la domanda corrente deve passare alla successiva"):
		return

	var quiz_data = instantiate_script("res://quiz_data.gd")
	if not check("quiz_data_inst", quiz_data != null, "Lo script quiz_data.gd deve istanziarsi senza errori"):
		return
	var records = quiz_data.get_sorted_records({"Storia": 10, "Scienza": 50, "Arte": 30})
	if not check("records_format", typeof(records) == TYPE_ARRAY and records.size() == 3, "get_sorted_records() deve restituire 3 elementi"):
		return
	var top_score: int = int(records[0].get("score", 0))
	var top_topic: String = str(records[0].get("topic", ""))
	check("records_order", top_score == 50 and top_topic == "Scienza", "Il primo elemento deve avere il punteggio più alto: Scienza con 50 punti (trovato: %s con %d punti)" % [top_topic, top_score])

